use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_runner_retries_transient_failures_with_bounded_delays() {
    let config = RetryConfig {
        max_attempts: 4,
        base_delay_ms: 5,
        max_delay_ms: 8,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        match calls {
            1 | 2 | 3 => Err(RetryError::Transient("busy".into())),
            _ => Ok(()),
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![5, 8, 8]);
}

